"""Customize scaffold generated by `flutter create` on GitHub Actions."""
from pathlib import Path
import shutil

root = Path(__file__).resolve().parent.parent
manifest = root / 'android/app/src/main/AndroidManifest.xml'
if not manifest.exists():
    raise SystemExit('Missing AndroidManifest.xml: run flutter create first')
text = manifest.read_text(encoding='utf-8')
text = text.replace('android:label="medieval_life"', 'android:label="ممالك الحياة"')
manifest.write_text(text, encoding='utf-8')

for size_name in ['mdpi', 'hdpi', 'xhdpi', 'xxhdpi', 'xxxhdpi']:
    source = root / f'assets/android_icon/mipmap-{size_name}/ic_launcher.png'
    destination = root / f'android/app/src/main/res/mipmap-{size_name}/ic_launcher.png'
    destination.parent.mkdir(parents=True, exist_ok=True)
    if not source.exists():
        raise SystemExit(f'Missing icon {source}')
    shutil.copyfile(source, destination)
print('Applied Arabic app label and custom icon.')
